arguments.command:
cd /tmp/sv-b4dec128a23444f9b23f6d3fb6fd854c/symbols

# The stripped binary has dynsym but not debug info. Let's try using nm on dynamic symbols
# and find the nearest symbol to each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== PC $addr ==="
  # Find the closest symbol at or before this address
  readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name = "??"; best_addr = 0; best_offset = target_dec }
    /FUNC/ {
      sym_addr = strtonum("0x" $2)
      sym_size = strtonum($3)
      if (sym_addr <= target_dec && sym_addr > best_addr) {
        best_addr = sym_addr
        best_name = $NF
        best_offset = target_dec - sym_addr
      }
    }
    END { printf "%s+0x%x\n", best_name, best_offset }
  '
done

