arguments.command:
cd /tmp/sv-b4dec128a23444f9b23f6d3fb6fd854c/symbols

# Use nm -D to get full symbol names, then find nearest
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk '/^[0-9a-f]+ [TtWw]/' | sort > /tmp/mono_syms.txt

